import Foundation

private typealias E = EvidenceSeed

/// Follow-up trials for the batch AQ everyday-crime stories.
extension FollowUpCases {
    static let batchAQ: [CaseTemplate] = [scooterTheft, streetShoutingAgain, prankAgain, porchPackagesTwo, contractorToolsTwo]

    static let scooterTheft = SmallCases.make(
        key: "story.followup.scooterTheft",
        category: .property,
        headlines: ["Electric Scooter Cut From Rack Near Campus", "Second Rack Theft Traced to Defendant From Earlier Case"],
        law: "misdLarceny",
        spec: "Stole an electric scooter valued at $750 belonging to {V}, on {DATE}.",
        ages: 18...40,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, an electric scooter was cut from a campus rack. A camera showed {D} loading it into a van. {DL} says {D.he} was moving a friend's scooter.",
        state: [E(.video, 3, "Campus Camera", "{D} cuts a lock and loads a scooter into a van."), E(.document, 2, "Receipt", "The scooter cost $750.")],
        defense: [E(.statement, 1, "Friend's Scooter", "{DL} says it was a friend's scooter.")],
        role: "Student",
        exam: [.direct("What happened to your scooter?", "\"I locked it to the campus rack outside the science building at about two in the afternoon and came out after class to find the cable cut and the scooter gone. It cost me $750.\""),
               .direct("How do you use that scooter?", "\"It is how I get to class and to my part-time job across town. Without it I am walking or waiting for buses, and I was late to work twice that week.\""),
               .direct("What did the campus camera show?", "\"It shows {DL} cutting the lock with a pair of cutters and rolling the scooter to a van parked at the curb. {D.He} loads it in the back and the van leaves.\""),
               .direct("Did anyone ask your permission?", "\"No one asked me anything. I never met {DL} before I saw {D.him} on the video, and I certainly did not lend that scooter to anybody.\""),
               .direct("How did you prove what you paid?", "\"I had the receipt in my email from when I bought it, and I printed it for the campus police. The serial number on it matches the one on the frame.\""),
               .direct("How did campus police identify the van?", "\"They ran the plate from the camera and it came back to {DL}. I was not part of that, I only heard it from the officer who called me.\""),
               .cross("Isn't it possible the scooter belonged to someone else?", "\"It is my scooter. I have the receipt and the serial number, and I locked it myself that morning.\""),
               .cross("You did not see who cut the lock, did you?", "\"Not in person. I was in class, and I only know what the camera shows afterward.\""),
               .cross("Could a friend of {DL}'s have asked {D.him} to move it?", "\"I have no idea what a friend might have said, but I did not give anyone permission to touch that scooter.\""),
               .cross("Your lock was not damaged before that day, was it?", "\"No, the cable was fine. I had used it for a year and never had a problem.\""),
               .cross("Have you ever lent your scooter to anyone on campus?", "\"A roommate borrowed it once, and I knew about it. I have never lent it to anyone outside my own friends.\"")],
        theory: ("{D} cut a campus lock and loaded someone else's scooter into a van.", "{D} was helping a friend move a scooter {D.he} believed was the friend's."),
        allocution: "\"I loaded that scooter into the van because I thought I was moving a friend's. I should have asked more, and I understand how it looked on camera. I've been in this courtroom before and I don't want to be back. I'll help return it.\"",
        truths: ("{DL} cut the lock on a scooter {D.he} knew belonged to someone else.", "A classmate who owned a scooter lost the key and asked {DL} to cut the cable and move it, but {DL} never checked that it was the same scooter."),
        defendant: [.direct("Did you cut the lock on that rack?", "\"I did. A friend had told me the scooter was his and that the key was lost, and asked me to cut it and move it to my van.\""),
               .direct("Who was the friend?", "\"A classmate. He asked me to move the scooter to my van because he had no way to carry it, and I did not ask many questions.\""),
               .direct("Why did you use your van?", "\"It is the only vehicle I have that holds a scooter, and I move things for friends all the time. I did not think there was anything wrong with it.\""),
               .direct("Did you know it was {V}'s scooter?", "\"No, I had never heard the name. I thought I was helping out a friend who had lost a key.\""),
               .direct("What did you do with the scooter after you loaded it?", "\"I drove it to my place and left it in the garage. I never sold it or tried to use it.\""),
               .direct("How do you feel about what happened?", "\"I feel bad that I did not ask more. I understand how it looked on camera, and I am sorry to {V}.\""),
               .cross("You cut a lock on a scooter that was not yours, didn't you?", "\"Yes, I cut the lock. I thought I was acting for a friend, but I admit I did the cutting.\""),
               .cross("A classmate told you it was his scooter, but you never saw proof, did you?", "\"No, I never saw a receipt or anything. I took his word.\""),
               .cross("You were here before, in {PRIORDATE}, and still did not ask questions?", "\"That is true. I should have known better after the last case, and I did not slow down.\""),
               .cross("The scooter was in your van when campus police found it?", "\"Yes, it was in my garage, and I told them right away where it was.\""),
               .cross("You never called {V} to ask whether the scooter was really your friend's?", "\"I did not know who {V} was. Nobody told me the name until the police did.\"")],
        openings: ("A scooter worth $750 was locked to a campus rack when a camera caught {D} cutting the cable and loading it into a van. {DL} has stood in this court before, in {PRIORDATE} for {PRIOR}, and this time the State will show the video, the receipt, and the van.", "The defense will present a driver who was told a friend's key was lost and who moved the scooter in broad daylight, on camera, in {D.his} own van. That is not how someone steals a scooter."),
        closings: ("The camera shows the lock cut, the scooter loaded, and the van leaving. {D} was in this court before and knew better.", "A friend said the scooter was his, and {D} cut the lock in public view with {D.his} own plate on camera. The State has not proved that {DL} knew it belonged to {V}."),
        timeline: [(0, "2 p.m.: {V} locks the scooter to the rack outside the science building."), (0, "2:40 p.m.: a camera records {DL} cutting the cable and loading the scooter into a van."), (1, "{V} finds the scooter gone and reports it to campus police."), (5, "Police trace the van's plate to {DL}.")],
        identified: "Campus camera video of {DL} loading the scooter.",
        impact: "Again, a stolen ride. I locked my scooter to the campus rack the way I always do and came out to a cut cable. It's how I get to class and to my part-time job. I'd already replaced one scooter after the first time. I'm getting tired of starting over.",
        genders: ["D": .male])

    static let streetShoutingAgain = SmallCases.make(
        key: "story.followup.streetShoutingAgain",
        category: .publicOrder,
        headlines: ["Man Shouting at Cars Again After Earlier Citation", "Deputy Finds Defendant From Patio Case in the Road"],
        law: "disorderly",
        spec: "Disturbed the peace by loud and abusive language in a public place, on {DATE}.",
        ages: 19...55,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, a deputy found {D} shouting at drivers from a median outside a different bar. {DL} refused to leave. {DL} says {D.he} was waiting for a ride.",
        state: [E(.statement, 3, "Deputy", "{D} shouted at cars and refused to leave."), E(.video, 2, "Bar Camera", "{D} on the median waving arms.")],
        defense: [E(.statement, 1, "Waiting", "{DL} says {D.he} was waiting for a ride.")],
        role: "Sheriff's deputy",
        exam: [.direct("What led you to the median that night?", "\"A bar owner called in someone shouting at passing cars from the median outside his place at about 12:30 a.m. I found {DL} standing in the middle of the road waving both arms.\""),
               .direct("What was {DL} saying?", "\"{D.He} was yelling at drivers as they went by, mostly cursing and telling them to slow down or stop. Some cars braked hard and swerved to avoid {D.him}.\""),
               .direct("Did you tell {DL} to leave?", "\"I did, about ten minutes after I arrived. I asked {D.him} twice to come off the median and go inside the bar or walk to the sidewalk.\""),
               .direct("How did {DL} respond?", "\"{D.He} said {D.he} was not going anywhere and kept yelling. It took a third request before {D.he} stepped back to the curb.\""),
               .direct("What does the bar camera show?", "\"It shows {DL} on the median with both arms up, in the glare of passing headlights. You can see cars slow and drift toward the other lane.\""),
               .direct("Was anyone else involved?", "\"There was another man near {DL} for part of it, also yelling. I spoke with him too and he left when told.\""),
               .direct("How would you describe the situation overall?", "\"It was a public road in front of a business with people trying to drive home. Shouting from the middle of it was a hazard as well as a disturbance.\""),
               .cross("{DL} said {D.he} was waiting for a ride, didn't {D.he}?", "\"{D.He} said so when I got out of my cruiser. I asked whether anyone was on the way, and {D.he} said a friend, but no ride came while I was there.\""),
               .cross("A median is a reasonable place to meet a ride, isn't it?", "\"Standing in the road at night is not safe, and the sidewalk is thirty feet away.\""),
               .cross("Did you see {DL} hit or threaten anyone?", "\"No, nobody was struck and I saw no threats. The complaint was about the shouting and the traffic.\""),
               .cross("{DL} left when you told {D.him} a third time, correct?", "\"Yes, {D.he} did, and {D.he} was not arrested on the spot. I wrote the citation later.\""),
               .cross("Was {DL} under the influence?", "\"I did not do a test. I could smell alcohol, but I cannot say how much.\"")],
        theory: ("{D} shouted abusively at drivers from the median of a public road and refused to leave.", "{D} was a person waiting for a late ride who got frustrated and left when asked."),
        allocution: "\"I'm sorry for standing in that median and yelling at drivers. I was waiting for a ride from a friend who was late, and I got frustrated. I should have gone inside or walked to a safer spot. I've been here before, and I'll be more careful.\"",
        truths: ("{DL} never had a ride coming and stood in the road yelling for no reason.", "A friend was late, and {DL} was waving to flag the friend down, with another friend nearby also yelling."),
        defendant: [.direct("What were you doing on the median?", "\"I was waiting for a ride from a friend who was late. It was cold, and I was getting frustrated.\""),
               .direct("Why were you shouting at cars?", "\"I was not shouting at the drivers, I was trying to flag my friend down. I yelled at one car that came too close.\""),
               .direct("Did a deputy tell you to leave?", "\"Yes, a deputy told me to move and I did not leave right away. I was arguing about it, and I should not have.\""),
               .direct("How long did it take you to leave?", "\"Maybe ten minutes in all. I walked to the sidewalk after the deputy asked the third time.\""),
               .direct("Did your ride come?", "\"My friend showed up after the deputy arrived. By then I had been warned and told to go home.\""),
               .direct("Have you thought about what you did that night?", "\"I should have gone inside the bar or walked to a safer spot, and I am sorry to the drivers.\""),
               .cross("You refused to leave when a deputy first told you to, didn't you?", "\"I stayed where I was for a few minutes. I did not do as I was told right away.\""),
               .cross("You said no ride came while the deputy was there?", "\"Right, my friend came later. I was tired and said I was going to wait.\""),
               .cross("You were drinking that night?", "\"I had a couple of drinks at the bar. I was not drunk.\""),
               .cross("You have been in this courtroom before, in {PRIORDATE}, haven't you?", "\"Yes, I have, and I should have walked away quietly this time. I did not use my head.\""),
               .cross("You stood in a lane of traffic, didn't you?", "\"I stood on the median, which is in the middle of the road. I know that now.\"")],
        openings: ("At 12:30 a.m. a deputy found {D} standing on a median outside a bar, shouting at passing cars. It took three requests before {D.he} stepped back, and a bar camera recorded the whole thing.", "{D} was waiting on a friend who ran late, cold and tired, outside a bar. The defense will show that a frustrated wait is not the same as abusive language aimed at the public."),
        closings: ("The bar camera shows {D} in the road with both arms up, and the deputy asked three times before {D.he} moved. Drivers braked and swerved around {D.him}, and that is a disturbance of the peace.", "A late ride, a cold night, and a person who left the median when told. The State has not shown abusive language meant to disturb anyone, only a frustrated wait."),
        timeline: [(0, "12:30 a.m.: {DL} stands on the median outside the bar, shouting at passing cars."), (0, "12:40 a.m.: a deputy arrives and asks {DL} to leave the road."), (0, "12:50 a.m.: after a third request, {DL} steps back to the curb."), (2, "The deputy issues a citation.")],
        identified: "A deputy's patrol report and the bar camera.",
        mood: .indifferent,
        genders: ["D": .male])

    static let prankAgain = SmallCases.make(
        key: "story.followup.prankAgain",
        category: .publicOrder,
        headlines: ["Another False Emergency Call Traced to Defendant", "Hoax Call Brings Deputies to Neighbor's House Again"],
        law: "falseReport",
        spec: "Willfully made a false report to law enforcement, on {DATE}.",
        ages: 18...30,
        victim: false,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, another call reported a break-in at the same neighbor's home. Deputies found nothing. The call traced to a phone used by {D}. {DL} says someone stole {D.his} phone.",
        state: [E(.digital, 3, "Call Trace", "The call came from {D}'s phone."), E(.document, 2, "Dispatch Log", "Deputies found no break-in.")],
        defense: [E(.statement, 1, "Stolen Phone", "{DL} says the phone was stolen.")],
        role: "911 dispatcher",
        exam: [.direct("What is your job with the county?", "\"I am a 911 dispatcher. I take calls from the public and send deputies and fire crews, and I have been doing it for nine years.\""),
               .direct("What was reported on this call?", "\"A caller said someone was breaking into the same neighbor's home that had been the subject of the earlier case. The caller gave the address and said the intruder was at the back door.\""),
               .direct("What did you do?", "\"I sent two deputies right away and kept the caller on the line. The caller hung up before I could ask more.\""),
               .direct("What did the deputies find?", "\"They found a locked house, an empty yard, and no sign of entry. The dispatch log has the arrival times and the all-clear.\""),
               .direct("Where did the call come from?", "\"The call trace shows it came from {D}'s phone. The number is registered to {DL}.\""),
               .direct("How long was the call?", "\"About forty seconds. The caller spoke quickly and sounded young, and I could hear laughing in the background.\""),
               .direct("Does it matter that this is the same address as before?", "\"It mattered to the deputies because the earlier case also involved that address. They treated this one with extra care.\""),
               .cross("{DL} says the phone was stolen, doesn't {D.he}?", "\"That is what I understand. I can only tell you whose number placed the call.\""),
               .cross("Did {DL} report a theft before this call?", "\"Not that I know of. I have no record of any report from {DL}.\""),
               .cross("Could someone else have used the phone?", "\"It is possible. A call trace shows which phone placed the call but not who held it.\""),
               .cross("You cannot say whose voice was on the call, can you?", "\"No, I cannot identify the voice. I am not able to tell you it was {DL}.\""),
               .cross("Dispatch recordings are kept, aren't they?", "\"Yes, they are, and the recording was preserved. I did not compare it to any other voice.\"")],
        theory: ("{D} made another false report to 911 about the same neighbor's home.", "Someone stole {D}'s phone and used it to place the call."),
        allocution: "\"I'm sorry for the trouble that call caused the deputies and that neighbor. My phone was stolen, and I didn't make it. I know it traces to my number, and I know my history in this courtroom, but I ask the court to believe me. I'd never put another family through that.\"",
        truths: ("{DL} never reported a theft because the phone was never stolen, and {D.he} made the call from it.", "{DL}'s phone was stolen for part of that evening and used by someone else, and {DL} simply never filed a report."),
        defendant: [.direct("Did you call 911 that night?", "\"No, I did not. I was not the one who made that call.\""),
               .direct("Where was your phone?", "\"It was stolen. I had it earlier in the evening and then I could not find it.\""),
               .direct("Did you report the phone stolen?", "\"Not right away. I forgot to, and then it was found, and I thought it was over.\""),
               .direct("Where were you at the time of the call?", "\"I was at home with my family. They saw me there all evening.\""),
               .direct("How did you get the phone back?", "\"It turned up near my house a day or two later. I did not know who had it, and I did not ask questions.\""),
               .direct("Why would you not want to make a call like that?", "\"I would never put another family through that, not after what happened last time.\""),
               .cross("The call came from your number, didn't it?", "\"Yes, it came from my number, and I know how that sounds.\""),
               .cross("You never reported the theft, did you?", "\"No, I did not, and I know that does not help me.\""),
               .cross("You have been in this courtroom before, in {PRIORDATE}, haven't you?", "\"Yes, I have. That is why this hurts so much, because I did not do this one.\""),
               .cross("Isn't it convenient that your phone went missing right then?", "\"It is what happened. I cannot make anyone believe it.\""),
               .cross("Your phone was found at home, correct?", "\"It was found near the house. I cannot say how it got there.\"")],
        openings: ("A 911 caller reported a break-in at the same neighbor's home that figured in {D}'s earlier case, in {PRIORDATE} for {PRIOR}. Deputies found nothing, and the call traced to a phone registered to {DL}.", "The defense will present a phone that was missing that evening and a person who was home with family. A number on a trace is not a voice, and the State cannot say who held that phone."),
        closings: ("The trace points to {D}'s phone, the call was about the same house as in the earlier case, and no theft was ever reported by {DL} to anyone.", "A phone can be taken and used by anyone. The State has no voice, no witness, and nothing but a number to put this call in {D}'s hands, and that is not enough."),
        timeline: [(0, "A caller reports a break-in at the neighbor's home."), (0, "Deputies respond and find no break-in."), (1, "The call is traced to {DL}'s phone."), (3, "{DL}'s phone is found near {D.his} home.")],
        identified: "The 911 call trace and dispatch log.",
        mood: .wantsConviction,
        impact: "It was the second false call to my house, and the deputies came running with their lights on while my family was inside. I was terrified until they told me nothing was there. I don't want that to happen again, and I'd like the person to understand how frightening it is.")

    static let porchPackagesTwo = SmallCases.make(
        key: "story.followup.porchPackagesTwo",
        category: .property,
        headlines: ["More Packages Stolen After Earlier Case", "Doorbell Camera Shows Defendant Taking Boxes Again"],
        law: "misdLarceny",
        spec: "Stole packages valued at $270 belonging to {V}, on {DATE}.",
        ages: 18...45,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, packages left at a different porch were taken. A doorbell camera showed {D} walking to the porch and leaving with boxes. {DL} says {D.he} thought they were {D.his}. The loss was put at $270.",
        state: [E(.video, 3, "Doorbell Camera", "{D} takes two boxes."), E(.document, 2, "Order Records", "Packages addressed to the resident.")],
        defense: [E(.statement, 1, "Mistake", "{DL} says {D.he} thought the boxes were {D.his}.")],
        role: "Resident",
        exam: [.direct("What happened to your deliveries?", "\"Two packages were delivered to my porch that afternoon. When I got home from work they were gone, and the porch was bare.\""),
               .direct("What was in them?", "\"A gift for my niece and a few things I had saved up for. Together they cost about $270.\""),
               .direct("What does your doorbell camera show?", "\"It shows {DL} walking up to the porch, looking at the boxes, and leaving with both of them. {D.He} was on and off my porch in about a minute.\""),
               .direct("Are those boxes yours?", "\"Yes. The order records show they were addressed to me, in my name, at my address.\""),
               .direct("Do you know {DL}?", "\"No, I never saw {D.him} before. I did not recognize {D.him} on the video and have no idea why {D.he} came to my house.\""),
               .direct("How did you find out who it was?", "\"The deputy matched the face from my video with the prior case in this court. I had nothing to do with that part.\""),
               .direct("How has this affected you?", "\"It makes me dread every delivery. I check the camera app whenever my phone buzzes.\""),
               .cross("{DL} says {D.he} thought the boxes were {D.his}, doesn't {D.he}?", "\"I have heard that, but the labels had my name on them, not {DL}'s.\""),
               .cross("Could someone have mixed up the address?", "\"The boxes were on my porch, at my address. That is not a mixed up address.\""),
               .cross("Did {DL} ring the bell or knock?", "\"No, not on the video. {D.He} walked up to the boxes and took them.\""),
               .cross("Did you speak with {DL} afterward?", "\"No, I have not spoken with {D.him}. Everything I know comes from the video and the deputy.\""),
               .cross("You cannot say what {DL} was thinking, can you?", "\"No, I cannot. I can only tell you what the video shows.\"")],
        theory: ("{D} walked up to a stranger's porch and took two packages.", "{D} mistook someone else's boxes for {D.his} own."),
        allocution: "\"I thought those boxes were mine, and I took them by mistake without reading the labels. I've been in this courtroom before, and I know that makes it harder to believe me. I'll pay back the two hundred seventy dollars.\"",
        truths: ("The labels bore {V}'s name and {DL} read it and took the boxes anyway.", "{DL} was expecting an order that day and took the wrong boxes without reading the labels."),
        defendant: [.direct("Did you take those boxes?", "\"Yes, I took them, by mistake. I thought they were mine.\""),
               .direct("Why did you think they were yours?", "\"I was expecting a delivery that day, and I saw boxes on a porch that looked like mine. I did not read the labels.\""),
               .direct("Did you go to the right house?", "\"I thought I had. I realize now I was a house or two off.\""),
               .direct("What did you do with the boxes?", "\"I took them home and opened one. When I saw it was not mine I should have brought it back, but I did not know what to do.\""),
               .direct("Did you try to hide anything?", "\"No. I walked right up in front of a doorbell camera. That is not what someone does who means to steal.\""),
               .direct("What do you wish you had done?", "\"I wish I had read the labels. I will pay back the two hundred seventy dollars.\""),
               .cross("The labels had a different name on them, didn't they?", "\"Yes, they did. I did not read them before I took the boxes.\""),
               .cross("You had an order that day, didn't you?", "\"I did, and I was waiting on it. That is why I assumed they were mine.\""),
               .cross("You were here in {PRIORDATE} for a different matter, weren't you?", "\"Yes, I was, and I know that makes it harder to believe me.\""),
               .cross("You opened one of the boxes, didn't you?", "\"I opened one, and then I saw the name. I should have taken it back that moment.\""),
               .cross("You never returned either one, did you?", "\"No. I was ashamed and I did not know how.\"")],
        openings: ("A doorbell camera caught {D} walking up to {V}'s porch and leaving with two boxes worth $270. {DL} was in this court before, in {PRIORDATE} for {PRIOR}, and the labels had someone else's name on them.", "The defense will present a person who was expecting a package that day and who walked up to a porch in plain view of a camera. That is a mistake about a label, and the State must prove a theft."),
        closings: ("Two boxes, a doorbell camera, and a label with {V}'s name on it. {D} took them in the middle of the afternoon and never brought either one back.", "{D} expected a delivery, misread a porch, and acted in full view of a camera. A mistake about whose boxes these were is not larceny, and {D.he} has offered to pay."),
        timeline: [(0, "A delivery of two packages lands on {V}'s porch."), (0, "{DL} walks up to the porch and takes both boxes while the doorbell camera records."), (0, "{V} comes home from work and finds the porch bare."), (1, "{V} reports the loss at $270 to deputies.")],
        identified: "A doorbell camera recording of the porch.",
        impact: "It happened again. I came home to find the porch bare, and the doorbell camera showed a person walking up and taking the boxes. They held a gift for my niece and a few things I'd saved up for. It makes me dread every delivery.",
        genders: ["D": .male])

    static let contractorToolsTwo = SmallCases.make(
        key: "story.followup.contractorToolsTwo",
        category: .property,
        headlines: ["Another Contractor's Tools Pawned", "Pawn Records Name Defendant From Earlier Larceny Case"],
        law: "possStolen",
        spec: "Possessed a drill set and compressor belonging to {V}, knowing them to be stolen, on {DATE}.",
        ages: 19...50,
        victim: true,
        summary: "After {DL}'s case in this court in {PRIORDATE} for {PRIOR}, pawn records show {D} sold a drill set and compressor stolen from a truck. {DL} says a cousin gave {D.him} the tools to sell.",
        state: [E(.document, 3, "Pawn Ticket", "{D}'s ID on the ticket."), E(.physical, 2, "Serial Numbers", "The serials match {V}'s receipt.")],
        defense: [E(.statement, 1, "Cousin", "{DL} says a cousin gave {D.him} the tools.")],
        role: "Contractor",
        exam: [.direct("What do you do for a living?", "\"I am a contractor. I do framing and finish work, and my tools are how I make my living.\""),
               .direct("What was taken from you?", "\"A cordless drill set and a compressor were stolen out of my truck's tool box over a weekend. I did not notice until Monday morning.\""),
               .direct("How did you learn where the tools went?", "\"A detective called me after a pawn shop reported items with my serial numbers. Both the drill set and the compressor were on the shop's list.\""),
               .direct("How do you know they are yours?", "\"I kept the receipts. The serial numbers on the drill set and the compressor match the numbers on my receipt.\""),
               .direct("What does the pawn ticket show?", "\"It shows the tools were pawned within two days of the theft, with {DL}'s ID on the ticket.\""),
               .direct("What did the loss cost you?", "\"I had to rent tools for two weeks and I lost part of a job. It cost me more than the tools were worth.\""),
               .direct("Do you know {DL}?", "\"No, I never knew the name until the detective gave it to me. I have never hired {D.him} or lent {D.him} anything.\""),
               .cross("{DL} says a cousin gave {D.him} the tools to sell, doesn't {D.he}?", "\"That is what I was told. I have never been given the cousin's name, so I cannot say anything about that.\""),
               .cross("Anyone could have broken into your truck, couldn't they?", "\"Yes, that is right. I do not know who broke in, only who pawned the tools.\""),
               .cross("Did you see {DL} anywhere near your truck?", "\"No, I did not. I was home that weekend, and the truck was in my driveway.\""),
               .cross("Are your serial numbers unique to your tools?", "\"Yes, they are, and that is how the pawn shop matched them. I have no doubt these were mine.\""),
               .cross("You never spoke with {DL} directly, did you?", "\"No, I did not. Everything I know comes from the detective and the pawn records.\"")],
        theory: ("{D} pawned tools stolen from a contractor's truck.", "{D} sold tools for a cousin without knowing they were stolen."),
